$Changed = New-Object System.Collections.Generic.List[string]
$Backups = @{}

function Step([string]$Text) {
    Write-Host ""
    Write-Host ("==> " + $Text) -ForegroundColor Cyan
}

function Ok([string]$Text) {
    Write-Host ("[OK] " + $Text) -ForegroundColor Green
}

function Warn([string]$Text) {
    Write-Host ("[AVISO] " + $Text) -ForegroundColor Yellow
}

function FullPath([string]$Relative) {
    return Join-Path $ProjectRoot ($Relative -replace "/", "\")
}

function NormalizeNewlines([string]$Value) {
    if ($null -eq $Value) { return "" }
    return $Value.Replace("`r`n", "`n").Replace("`r", "`n")
}

function DecodePatch([string]$Name) {
    return NormalizeNewlines (
        [Text.Encoding]::UTF8.GetString(
            [Convert]::FromBase64String($Patch[$Name])
        )
    )
}

function Backup([string]$Relative) {
    $source = FullPath $Relative

    if (-not (Test-Path -LiteralPath $source -PathType Leaf)) {
        return
    }

    $destination = Join-Path $BackupRoot ($Relative -replace "/", "\")
    [IO.Directory]::CreateDirectory((Split-Path -Parent $destination)) | Out-Null
    Copy-Item -LiteralPath $source -Destination $destination -Force
    $Backups[$Relative] = $destination
}

function MarkChanged([string]$Relative) {
    if (-not $Changed.Contains($Relative)) {
        $Changed.Add($Relative)
    }
}

function CountExact([string]$Text, [string]$Needle) {
    $haystack = NormalizeNewlines $Text
    $target = NormalizeNewlines $Needle
    $count = 0
    $start = 0

    while ($true) {
        $index = $haystack.IndexOf(
            $target,
            $start,
            [StringComparison]::Ordinal
        )

        if ($index -lt 0) { break }

        $count++
        $start = $index + $target.Length
    }

    return $count
}

function WriteBytesWithRetry([string]$Relative, [byte[]]$Bytes) {
    $path = FullPath $Relative
    $directory = Split-Path -Parent $path
    [IO.Directory]::CreateDirectory($directory) | Out-Null

    $temp = Join-Path $directory (
        "." +
        [IO.Path]::GetFileName($path) +
        ".orcaly-fase7-" +
        [Guid]::NewGuid().ToString("N") +
        ".tmp"
    )

    try {
        [IO.File]::WriteAllBytes($temp, $Bytes)
        $written = $false
        $lastError = $null

        for ($attempt = 1; $attempt -le 8; $attempt++) {
            try {
                if (Test-Path -LiteralPath $path -PathType Leaf) {
                    [IO.File]::Copy($temp, $path, $true)
                }
                else {
                    [IO.File]::Move($temp, $path)
                }

                $written = $true
                break
            }
            catch {
                $lastError = $_.Exception
                [GC]::Collect()
                [GC]::WaitForPendingFinalizers()
                Start-Sleep -Milliseconds (250 * $attempt)
            }
        }

        if (-not $written) {
            throw (
                "Windows manteve o arquivo bloqueado: " +
                $Relative +
                ". Feche npm run dev/VS Code e tente novamente. " +
                $(if ($lastError) { $lastError.Message } else { "" })
            )
        }
    }
    finally {
        Remove-Item -LiteralPath $temp -Force -ErrorAction SilentlyContinue
    }
}

function WriteTextWithRetry([string]$Relative, [string]$Text) {
    $bytes = [Text.Encoding]::UTF8.GetBytes((NormalizeNewlines $Text))
    WriteBytesWithRetry $Relative $bytes
}

function WriteGenerated([string]$Relative) {
    $path = FullPath $Relative

    if (Test-Path -LiteralPath $path -PathType Leaf) {
        $actual = (Get-FileHash $path -Algorithm SHA256).Hash.ToUpperInvariant()

        if ($actual -eq $ExpectedSha[$Relative]) {
            Ok ($Relative + " ja corresponde a FASE 7.")
            return
        }

        throw ($Relative + " ja existe com conteudo diferente.")
    }

    $bytes = [Convert]::FromBase64String($GeneratedFiles[$Relative])
    WriteBytesWithRetry $Relative $bytes

    $actual = (Get-FileHash (FullPath $Relative) -Algorithm SHA256).Hash.ToUpperInvariant()

    if ($actual -ne $ExpectedSha[$Relative]) {
        throw ("SHA256 inesperado depois de gravar " + $Relative)
    }

    MarkChanged $Relative
    Ok ($Relative + " criado.")
}

function ReplaceExact(
    [string]$Relative,
    [string]$BeforeName,
    [string]$AfterName,
    [string]$Label
) {
    $path = FullPath $Relative

    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
        throw ("Arquivo ausente: " + $Relative)
    }

    $text = NormalizeNewlines ([IO.File]::ReadAllText($path))
    $before = DecodePatch $BeforeName
    $after = DecodePatch $AfterName

    if ($text.Contains($after)) {
        Ok ($Label + " ja aplicado.")
        return
    }

    $count = CountExact $text $before

    if ($count -ne 1) {
        throw (
            $Label +
            ": trecho esperado encontrado " +
            $count +
            " vez(es). Nao vou adivinhar o merge."
        )
    }

    Backup $Relative
    $updated = $text.Replace($before, $after)
    WriteTextWithRetry $Relative $updated
    MarkChanged $Relative
    Ok $Label
}

function AssertCheck([bool]$Passed, [string]$Name) {
    if (-not $Passed) {
        throw ("Validacao falhou: " + $Name)
    }
    Ok $Name
}

function Rollback {
    [array]$items = @($Changed)
    [Array]::Reverse($items)

    foreach ($relative in $items) {
        if ($Backups.ContainsKey($relative)) {
            Copy-Item -LiteralPath $Backups[$relative] -Destination (FullPath $relative) -Force
            Warn ("Restaurado: " + $relative)
        }
        else {
            Remove-Item -LiteralPath (FullPath $relative) -Force -ErrorAction SilentlyContinue
            Warn ("Removido: " + $relative)
        }
    }
}

